helper_sources.draw_internal_bend_mask.ps1:
param([string]$diagramRoot)
Add-Type -AssemblyName System.Drawing
$diagramData=Get-Content -LiteralPath "$diagramRoot/comparison.json" -Raw -Encoding UTF8 | ConvertFrom-Json
$diagramBitmap=New-Object System.Drawing.Bitmap 1300,620
$diagramGraphics=[System.Drawing.Graphics]::FromImage($diagramBitmap)
$diagramGraphics.Clear([System.Drawing.Color]::White)
$diagramFont=New-Object System.Drawing.Font 'Arial',14
$diagramSmallFont=New-Object System.Drawing.Font 'Arial',10
$diagramBrushes=@{
 road=New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(145,161,173))
 pavement=New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(222,184,119))
}
$diagramGraphics.DrawString('Finished mesh comparison | Private internal bend on one unchanged spline',$diagramFont,[System.Drawing.Brushes]::Black,20,12)
for ($diagramIndex=0;$diagramIndex -lt 1;$diagramIndex++) {
 $diagramPanel=$diagramData.panels[$diagramIndex]
 for ($diagramColumn=0;$diagramColumn -lt 2;$diagramColumn++) {
  $diagramKey=if ($diagramColumn -eq 0) {'before'} else {'after'}
  $diagramLabel=if ($diagramColumn -eq 0) {'Before'} else {'Private bend geometry'}
  $diagramCenterX=325+650*$diagramColumn
  $diagramCenterY=330+420*$diagramIndex
  $diagramScale=14.5
  $diagramGraphics.DrawString("$diagramLabel | $($diagramPanel.title)",$diagramFont,[System.Drawing.Brushes]::Black,[single](20+650*$diagramColumn),[single](48+420*$diagramIndex))
  $diagramGraphics.DrawString(($diagramPanel.ids -join ' / '),$diagramSmallFont,[System.Drawing.Brushes]::DimGray,[single](20+650*$diagramColumn),[single](75+420*$diagramIndex))
  $diagramGraphics.SetClip([System.Drawing.RectangleF]::new([single](20+650*$diagramColumn),[single](100+420*$diagramIndex),610,460))
  foreach ($diagramPolygon in $diagramPanel.$diagramKey) {
   $diagramPoints=[System.Drawing.PointF[]]@($diagramPolygon.points | ForEach-Object {
    [System.Drawing.PointF]::new([single]($diagramCenterX+$diagramScale*$_[0]),[single]($diagramCenterY-$diagramScale*$_[1]))
   })
   $diagramGraphics.FillPolygon($diagramBrushes[$diagramPolygon.kind],$diagramPoints)
  }
  $diagramGraphics.DrawLine([System.Drawing.Pens]::SteelBlue,[single]($diagramCenterX-3),[single]$diagramCenterY,[single]($diagramCenterX+3),[single]$diagramCenterY)
  $diagramGraphics.DrawLine([System.Drawing.Pens]::SteelBlue,[single]$diagramCenterX,[single]($diagramCenterY-3),[single]$diagramCenterX,[single]($diagramCenterY+3))
  $diagramGraphics.ResetClip()
 }
}
$diagramGraphics.DrawString('Grey: road | Tan: kerb / pavement | Blue: source node | Same scale | Not native / terrain acceptance',$diagramFont,[System.Drawing.Brushes]::Black,20,590)
$diagramBitmap.Save([System.IO.Path]::GetFullPath("$diagramRoot/comparison.png"),[System.Drawing.Imaging.ImageFormat]::Png)
$diagramGraphics.Dispose();$diagramBitmap.Dispose();$diagramFont.Dispose();$diagramSmallFont.Dispose()
foreach ($diagramBrush in $diagramBrushes.Values) {$diagramBrush.Dispose()}
